namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void initial(){MainWindow window;window.show();window.activateWindow();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");grid->setFocus();const auto before=window.currentSession().snapshot();bool opened=false;double current=-1;QTimer::singleShot(0,[&]{if(auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget())){opened=dialog->windowTitle()=="Column Width";current=dialog->doubleValue();dialog->reject();}});QTest::keyClick(grid,Qt::Key_Alt);QTest::keyClick(grid,Qt::Key_O);QTest::keyClick(grid,Qt::Key_C);QTest::keyClick(grid,Qt::Key_W);require(opened&&std::abs(current-8.43)<0.001,"initial Alt O C W dialog displays the observed 8.43 character width");require(grid->columnWidth(0)==64&&grid->rowHeight(0)==20,"initial blank sheet uses the observed 64-pixel columns and 20-pixel rows at 100 percent");require(window.currentSession().snapshot()==before,"cancelling the initial Column Width dialog leaves workbook/history unchanged");require(window.executeCommand("columns.size",{{"size",2.0}})&&grid->columnWidth(0)==19,"explicit two-character columns use the same Excel Normal seven-pixel digit calibration");}
void font(bool dialog,bool quick=false){MainWindow window;window.show();window.activateWindow();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());require(model->apply(Json::array({{{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",1},{"input","Keep"}} ,{{"type","set_sheet_layout"},{"sheet","sheet-1"},{"rows",Json::array({{{"index",4},{"size",30.0}}})}}})),"seed existing input and explicit row height");grid->setFocus();QTest::keyClick(grid,Qt::Key_A,Qt::ControlModifier);const auto before=window.currentSession().snapshot();if(dialog){bool opened=false;QTimer::singleShot(0,[&]{if(auto* modal=qobject_cast<QDialog*>(QApplication::activeModalWidget())){auto* size=modal->findChild<QSpinBox*>("formatCells.fontSize");if(size){modal->findChild<QTabWidget*>("formatCells.tabs")->setCurrentIndex(2);size->setValue(12);opened=true;modal->accept();}else modal->reject();}});QTest::keyClick(grid,Qt::Key_1,Qt::ControlModifier);require(opened,"Ctrl+1 exposes whole-sheet Font size");}else if(quick){QTest::keyClick(grid,Qt::Key_Alt);QTest::keyClick(grid,Qt::Key_8);auto* size=window.findChild<QSpinBox*>("ribbon.fontSize");auto* editor=size?size->findChild<QLineEdit*>():nullptr;require(size&&editor&&(size->hasFocus()||editor->hasFocus()),"Alt+8 reveals and focuses the actual Home font-size field");QTest::keyClicks(size,"12");QTest::keyClick(size,Qt::Key_Return);}else{auto* size=window.findChild<QSpinBox*>("ribbon.fontSize");size->setFocus();QTest::keyClick(size,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(size,"12");QTest::keyClick(size,Qt::Key_Return);}const auto& sheet=window.currentSession().snapshotView().at("sheets")[0];require(sheet.value("defaultRowHeight",0.0)==15.75&&grid->rowHeight(0)==21&&grid->rowHeight(5)==21,"whole-sheet 12-point font sets a sparse 15.75-point default row height and displays 21-pixel rows");require(grid->rowHeight(3)==40&&model->raw(0,0)=="Keep"&&model->cellStyle(5,5).value("fontSize",0)==12,"whole-sheet font preserves explicit row heights and values, including style on unstored cells");require(window.executeCommand("undo")&&window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"font and default row height are one undoable edit");require(window.executeCommand("redo"),"redo whole-sheet font and row height");QTemporaryDir files;const auto path=files.filePath("font12.xlsx");require(window.saveWorkbook(path),"save whole-sheet font geometry");auto native=readWorkbook(path.toStdString());require(native.workbook.at("sheets")[0].at("defaultRowHeight")==15.75&&native.entries.at(native.sheetParts.begin()->second).find("defaultRowHeight=\"15.75\"")!=std::string::npos,"native XLSX stores the default row height rather than synthesizing a million row records");require(window.openWorkbook(path)&&grid->rowHeight(0)==21&&grid->rowHeight(3)==40&&model->cellStyle(5,5).value("fontSize",0)==12,"native reopen retains font and row geometry");}
void fontTyping(){
 for(const bool focusOut:{false,true}){
  MainWindow window;window.show();window.activateWindow();QApplication::processEvents();auto* grid=window.findChild<QTableView*>("worksheet.grid");auto* model=dynamic_cast<WorksheetModel*>(grid->model());
  require(model->apply(Json::array({
   {{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",1},{"input","Keep"},{"style",{{"bold",true},{"note","preserve"}}}},
   {{"type","set_cell"},{"sheet","sheet-1"},{"row",2},{"col",2},{"input","=1+2"}},
   {{"type","set_sheet_layout"},{"sheet","sheet-1"},{"defaultStyle",{{"fontFamily","Calibri"},{"color","#123456"}}},{"rows",Json::array({{{"index",4},{"size",30.0}}})},{"columns",Json::array({{{"index",3},{"size",18.0}}})}}
  })),"prepare sparse whole-sheet font defaults, values and explicit dimensions");
  window.recalculateNow();const auto calculated=model->calculatedSnapshot();require(model->numericValue(1,1)==3,"prepare a real current formula result for delayed publication");
  grid->setFocus();QTest::keyClick(grid,Qt::Key_A,Qt::ControlModifier);const auto selection=grid->selectionModel()->selection();const auto before=window.currentSession().snapshot();const auto history=window.currentSession().historyBytes();const int defaultRowHeight=grid->rowHeight(0),explicitRowHeight=grid->rowHeight(3),columnWidth=grid->columnWidth(2);const int requested=focusOut?72:96;
  auto* size=window.findChild<QSpinBox*>("ribbon.fontSize");require(size,"Home has the native font-size field");size->setFocus();QTest::keyClick(size,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(size,QString::number(requested).toLatin1());QApplication::processEvents();
  require(size->text()==QString::number(requested)&&window.currentSession().snapshot()==before&&window.currentSession().historyBytes()==history&&grid->rowHeight(0)==defaultRowHeight,"typing a whole-sheet font size remains a draft without intermediate formatting transactions");
  model->setCalculated(calculated);
  require(size->text()==QString::number(requested)&&window.currentSession().snapshot()==before&&window.currentSession().historyBytes()==history,"publishing current calculation results must preserve the focused uncommitted font-size draft");
  if(focusOut)grid->setFocus();else QTest::keyClick(size,Qt::Key_Return);QApplication::processEvents();const auto& after=window.currentSession().snapshotView();const auto& sheet=after.at("sheets")[0];
  require(after.at("revision").get<std::uint64_t>()==before.at("revision").get<std::uint64_t>()+1&&sheet.at("defaultStyle").at("fontSize")==requested&&model->cellStyle(99999,999).at("fontSize")==requested,"Return or focus loss applies the final font once to sparse worksheet defaults");
  require(sheet.at("cells").size()==2&&model->raw(0,0)=="Keep"&&model->raw(1,1)=="=1+2"&&model->cellStyle(0,0).at("bold")==true&&model->cellStyle(0,0).at("note")=="preserve"&&sheet.at("defaultStyle").at("color")=="#123456","committed font preserves sparse cells, inputs, formulas, emphasis and inherited color");
  require(sheet.at("rowLayout")==before.at("sheets")[0].at("rowLayout")&&sheet.at("columnLayout")==before.at("sheets")[0].at("columnLayout")&&grid->rowHeight(3)==explicitRowHeight&&grid->columnWidth(2)==columnWidth&&grid->selectionModel()->selection()==selection,"committed font preserves explicit dimensions and the whole-sheet selection");
  require(window.executeCommand("undo")&&window.currentSession().snapshotView().at("sheets")==before.at("sheets")&&grid->rowHeight(0)==defaultRowHeight,"one Undo restores the font defaults, stored styles and default row height exactly");
  grid->setFocus();require(size->value()==11,"normal ribbon synchronization resumes after font draft commit and Undo");
 }
}
void nativeDefault(bool legacy=false){WorkbookSession session;require(session.apply(0,Json::array({{{"type","set_sheet_layout"},{"sheet","sheet-1"},{"defaultColumnWidth",12.0}}})),"sheet layout accepts a bounded native default column width");QTemporaryDir files;const auto path=files.filePath("native-default-width.xlsx");writeWorkbook(path.toStdString(),session.snapshotView());auto native=readWorkbook(path.toStdString());require(native.workbook.at("sheets")[0].value("defaultColumnWidth",0.0)==12.0&&native.entries.at(native.sheetParts.begin()->second).find("defaultColWidth=\"12\"")!=std::string::npos,"default column width survives as the native sheetFormatPr field");MainWindow window;require(window.openWorkbook(path),"open custom native default column width");auto* grid=window.findChild<QTableView*>("worksheet.grid");require(grid->columnWidth(0)==84&&grid->columnWidth(100)==84,"native default column width applies to unstored columns using the same Normal digit calibration");if(legacy){const auto xls=files.filePath("native-default-width.xls");MainWindow authored;auto* authoredGrid=authored.findChild<QTableView*>("worksheet.grid");auto* authoredModel=dynamic_cast<WorksheetModel*>(authoredGrid->model());require(authoredModel->apply(Json::array({{{"type","set_sheet_layout"},{"sheet","sheet-1"},{"defaultColumnWidth",12.0}}})),"set the same native default on a fresh workbook supported by BIFF export");require(authored.saveWorkbook(xls)&&authored.openWorkbook(xls)&&authoredGrid->columnWidth(0)==84&&authoredGrid->columnWidth(255)==84,"native BIFF8 save/reopen retains default column width in every representable unstored column");MainWindow blank;auto* cells=blank.findChild<QTableView*>("worksheet.grid");const auto blankXls=files.filePath("blank-default-width.xls");require(blank.saveWorkbook(blankXls)&&blank.openWorkbook(blankXls)&&cells->columnWidth(0)==64,"a new blank BIFF8 workbook retains the observed standard column width");}}
}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const auto mode=argc>1?std::string(argv[1]):std::string("initial");if(mode=="initial")initial();else if(mode=="font_typing")fontTyping();else if(mode=="native"||mode=="biff")nativeDefault(mode=="biff");else{font(mode=="dialog",mode=="qat");if(mode=="ribbon")fontTyping();}std::cout<<"Default worksheet geometry passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
